// Get manuscript ID from the webhook (always available)
const manuscriptId = $('Webhook').first().json.body.manuscriptId;

console.log(`Chapter analysis complete for manuscript: ${manuscriptId}`);

// Pass the manuscript ID forward
return {
  json: {
    manuscriptId: manuscriptId,
    analysisCompleted: true,
    timestamp: new Date().toISOString()
  }
};

// Parse Jordan's analysis response
const response = $input.first().json;
let analysisText = response.output || response.text || JSON.stringify(response);

// Clean up markdown code blocks if present
analysisText = analysisText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

console.log('=== PARSING JORDAN ANALYSIS ===');
console.log('Raw response length:', analysisText.length);
console.log('First 200 chars:', analysisText.substring(0, 200));

let parsed;
try {
  parsed = JSON.parse(analysisText);
} catch (error) {
  console.error('JSON parse error:', error);
  console.log('Failed to parse:', analysisText);

// Return empty array if parsing fails or no suggestions
// This prevents the SQL node from trying to insert anything
return [];
}

// Validate structure
if (!parsed.suggestions || !Array.isArray(parsed.suggestions)) {
  console.error('Invalid response structure:', parsed);
  return [{
    json: {
      suggestions: [],
      manuscriptId: $('Webhook').first().json.body.manuscriptId,
      chapterNumber: $('Webhook').first().json.body.chapterNumber
    }
  }];
}

console.log(`✅ Parsed ${parsed.suggestions.length} corrections from Jordan`);

// Get webhook data
const webhookData = $('Webhook').first().json.body;

// After parsing, sort before returning
const formattedSuggestions = parsed.suggestions
  .sort((a, b) => (a.approximate_paragraph || 0) - (b.approximate_paragraph || 0))
  .map((suggestion, index) => ({
    manuscript_id: webhookData.manuscriptId,
    chapter_number: webhookData.chapterNumber,
    element_type: suggestion.category,
    severity: suggestion.severity,
    quoted_text: suggestion.quoted_text || '',
    issue_description: suggestion.issue,
    editor_suggestion: suggestion.suggestion,
    start_position: suggestion.approximate_paragraph || index,  // Use paragraph as position
    end_position: 0,
    status: 'flagged'
  }));

console.log('✅ Formatted corrections for database insertion');

return formattedSuggestions.map(s => ({ json: s }));

const cellReturn = $input.first().json;
let terminalReason = null;
if (!cellReturn.ok) {
  terminalReason = cellReturn.terminal_reason || 'unknown';
}
return [{ json: {
  ok: !!cellReturn.ok,
  output: cellReturn.ok ? (cellReturn.content || '') : '',
  cell_terminal_reason: terminalReason,
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];

